VAR
    Overload_Timer : TON;
END_VAR

// Winding temperature protection for Class F insulation (limit 140 degC)
// Implement a 3-second delay to prevent nuisance tripping from signal noise
Overload_Timer(IN := (Motor_Winding_Temp > 140.0), PT := T#3S);

IF Overload_Timer.Q THEN
    Motor_Stop := TRUE;
    Overload_Alarm := TRUE;
END_IF;

IF Fault_Reset THEN
    Overload_Alarm := FALSE;
END_IF;

